/* ---- src/alloc/tld-alloc.c ---- */
#include <stdlib.h>

#define ALIGN16 16
typedef struct {
        uint32_t aligned : 1;
        uint32_t dim1 : 31;
        uint32_t dim2;
        void* ptr;
} __attribute__((aligned(ALIGN16))) tld__mem_info;
#undef ALIGN16

#define TLD__MEM_SHIFT sizeof(tld__mem_info)

int tld_galloc_dim1(void* ptr,uint32_t* d)
{
        tld__mem_info* h = NULL;
        ASSERT(ptr != NULL, "No galloc pointer");
        ASSERT(d != NULL, "No output pointer");
        h = (tld__mem_info*) ( (size_t)ptr - TLD__MEM_SHIFT);
        *d = h->dim1;
        return OK;
ERROR:
        return FAIL;
}

int tld_galloc_dim2(void* ptr,uint32_t* d)
{
        tld__mem_info* h = NULL;
        ASSERT(ptr != NULL, "No galloc pointer");
        ASSERT(d != NULL, "No output pointer");
        h = (tld__mem_info*) ( (size_t)ptr - TLD__MEM_SHIFT);
        *d = h->dim2;
        return OK;
ERROR:
        return FAIL;
}

void tld__gfree(void* p)
{
        tld__mem_info* h = NULL;
        if(p == NULL){
                return;
        }
        h = (tld__mem_info*) ( (size_t)p - TLD__MEM_SHIFT);
        if(h->ptr){
                MFREE(h->ptr);
        }
        MFREE(h);
}

int tld__galloc_too_few(void)
{
        ERROR_MSG("Too few parameters passed to galloc.\nExpects at least 2");
        return OK;
ERROR:
        return FAIL;
}

void* tld__galloc(size_t rsize, size_t tsize, int dim1, int dim2)
{
        tld__mem_info* h = NULL;
        void* tmp = NULL;

        ASSERT(dim1 >= 1,"DIM1 is too small: %d",dim1);
        ASSERT(dim2 >= 0,"DIM2 is negative: %d",dim2);
        ASSERT(tsize > 0 && rsize > 0,"Element size is 0");
        /* All sizes in size_t; refuse requests whose byte count does not fit. */
        ASSERT((size_t)dim1 <= (SIZE_MAX - TLD__MEM_SHIFT) / rsize,
               "Allocation of %d x %zu bytes is too large", dim1, rsize);
        if(dim2){
                ASSERT((size_t)dim1 <= SIZE_MAX / (size_t)dim2 / tsize,
                       "Allocation of %d x %d x %zu bytes is too large", dim1, dim2, tsize);
        }

        MMALLOC(tmp, (size_t)dim1 * rsize + TLD__MEM_SHIFT);

        h = (tld__mem_info*)(tmp);
        h->aligned = 0u;
        h->dim1  = dim1;
        h->dim2  = dim2;
        h->ptr = NULL;
        if(dim2){
                MMALLOC(h->ptr, (size_t)dim1 * (size_t)dim2 * tsize);
        }
        return (void *)((size_t)tmp + TLD__MEM_SHIFT);
ERROR:
        MFREE(tmp);
        return NULL;
}

int tld__galloc_data(void* ptr,void** d)
{
        if(ptr){
                tld__mem_info* h = NULL;
                h = (tld__mem_info*) ( (size_t)ptr - TLD__MEM_SHIFT);
                *d = h->ptr;
                return OK;
        }
        return FAIL;
}

#undef TLD__MEM_SHIFT
/* ---- src/string/tld-string.c ---- */

#include <stddef.h>
#include <stdint.h>
#include <string.h>

static int tld__strbuf_resize(tld_strbuf *b, int new_size);
static int tld__strbuf_ensure_size(tld_strbuf *b, size_t size);
static ptrdiff_t tld__strbuf_offset(const tld_strbuf *b, const char *p);

int tld_strbuf_alloc(tld_strbuf **buffer, int size)
{
        tld_strbuf* b = NULL;
        ASSERT(buffer != NULL, "No output pointer");
        ASSERT(size >= 0, "Negative buffer size: %d", size);
        MMALLOC(b,sizeof(tld_strbuf));
        if(size == 0){
                size = 1024;
        }
        b->alloc_len = size;
        b->len = 0;
        b->str = NULL;
        galloc(&b->str, b->alloc_len);
        b->str[0] = 0;

        *buffer = b;
        return OK;
ERROR:
        tld_strbuf_free(b);
        return FAIL;
}

void tld_strbuf_free(tld_strbuf *b)
{
        if(b){
                if(b->str){
                        gfree(b->str);
                }
                MFREE(b);
        }
}

int tld_strbuf_clear(tld_strbuf *b)
{
        ASSERT(b != NULL,"No buffer");
        b->len = 0;
        b->str[b->len] = 0;

        return OK;
ERROR:
        return FAIL;
}

int tld__strbuf_resize(tld_strbuf *b, int new_size)
{
        uint8_t* tmp = NULL;
        if (new_size > b->alloc_len){
                galloc(&tmp , new_size);

                memcpy(tmp,b->str,b->len);
                tmp[b->len] = 0;

                gfree(b->str);
                b->str = tmp;
                b->alloc_len = new_size;
        }
        return OK;
ERROR:
        if(tmp){
                gfree(tmp);
        }
        return FAIL;
}

/* Make room for size more bytes and the NUL. Sizes are size_t so nothing wraps; a
   buffer cannot grow past INT32_MAX bytes (len and alloc_len are int32_t). */
int tld__strbuf_ensure_size(tld_strbuf *b, size_t size)
{
        ASSERT(b->len >= 0 && size <= (size_t)INT32_MAX - (size_t)b->len - 1,
               "String buffer would exceed %d bytes", INT32_MAX);
        size_t need = (size_t)b->len + size + 1;
        if(need > (size_t)b->alloc_len){
                size_t grow = (size_t)b->alloc_len * 2;
                if(grow < need){
                        grow = need;
                }
                if(grow > (size_t)INT32_MAX){
                        grow = (size_t)INT32_MAX;
                }
                RUN(tld__strbuf_resize(b, (int)grow));
        }
        return OK;
ERROR:
        return FAIL;
}

/* The offset of p in b's bytes, or -1 when p points elsewhere. Text passed to an
   append can come from the buffer itself (TLD_STR(b)), and growing the buffer moves
   it, so callers re-derive the pointer from the offset after growing. */
ptrdiff_t tld__strbuf_offset(const tld_strbuf *b, const char *p)
{
        uintptr_t start = (uintptr_t) b->str;
        uintptr_t q = (uintptr_t) p;
        if(q >= start && q < start + (uintptr_t) b->alloc_len){
                return (ptrdiff_t) (q - start);
        }
        return -1;
}

int tld_strbuf_copy(tld_strbuf *t, tld_strbuf *s)
{
        ASSERT(t != NULL, "No buffer");
        ASSERT(s != NULL, "No buffer");
        if(t == s){
                return OK;
        }
        /* room for s->len bytes in total; t is unchanged if this fails */
        RUN(tld__strbuf_ensure_size(t, s->len > t->len ? (size_t)(s->len - t->len) : 0));

        memcpy(t->str, s->str, s->len);
        t->len = s->len;
        t->str[t->len] = 0;
        return OK;
ERROR:
        return FAIL;
}

int tld_strbuf_append(tld_strbuf *b, const char *content)
{
        ASSERT(content != NULL, "No text");
        return tld_strbuf_append_n(b, content, strlen(content));
ERROR:
        return FAIL;
}

int tld_strbuf_append_n(tld_strbuf *b, const char *s, size_t n)
{
        ptrdiff_t off = 0;
        ASSERT(b != NULL, "No buffer");
        ASSERT(s != NULL || n == 0, "No text");
        off = tld__strbuf_offset(b, s);

        RUN(tld__strbuf_ensure_size(b, n));
        if(off >= 0){
                s = TLD_STR(b) + off;
        }
        if(n){
                memmove(b->str + b->len, s, n);
        }
        b->len += (int32_t)n;
        b->str[b->len] = 0;

        return OK;
ERROR:
        return FAIL;
}

int tld_strbuf_append_char(tld_strbuf *b, char c)
{
        ASSERT(b != NULL, "No buffer");
        RUN(tld__strbuf_ensure_size(b, 1));
        b->str[b->len] = c;
        b->len++;
        b->str[b->len] = 0;

        return OK;
ERROR:
        return FAIL;
}

int tld_strbuf_prepend(tld_strbuf *b, const char *content)
{
        size_t size = 0;
        ptrdiff_t off = 0;
        ASSERT(b != NULL, "No buffer");
        ASSERT(content != NULL, "No text");
        size = strlen(content);
        off = tld__strbuf_offset(b, content);

        RUN(tld__strbuf_ensure_size(b, size));
        memmove(b->str + size, b->str, b->len);
        if(off >= 0){
                /* the text came from b and has just moved size bytes right */
                content = TLD_STR(b) + off + size;
        }
        memmove(b->str, content, size);
        b->len += (int32_t)size;
        b->str[b->len] = 0;
        return OK;
ERROR:
        return FAIL;
}
