#include <time.h>
#include <stdio.h>


void tld__timer(int end)
{
        static double time_start;
        struct timespec now = {0};
        double t = 0.0;

        if(timespec_get(&now, TIME_UTC) != TIME_UTC){
                now.tv_sec = time(NULL);
        }
        t = (double) now.tv_sec + (double) now.tv_nsec / 1e9;
        if(end){
                LOG_MSG("exec time: %1.2fs", t - time_start);
                return;
        }
        time_start = t;
}
/* ---- src/bitfield/tld-bitfield.c ---- */

#define BITS_W 64
#define BIT_SHIFT 6
#define BIT_MASK 0x3F

static inline int tld__bitfield_popcount(uint64_t x);
/* Here is a piece of code to calculate the hamming distance
        between two bitfields using the popcount instruction
        available on most modern CPUs
 */

int tld_bitfield_alloc(tld_bitfield **bit_f, int32_t size)
{
        tld_bitfield* b = NULL;
        ASSERT(bit_f != NULL, "No output pointer");
        MMALLOC(b, sizeof(tld_bitfield));
        b->alloc_len = 1 + size / BITS_W;
        galloc(&b->m, b->alloc_len);
        b->len = size;

        RUN(tld_bitfield_reset(b));
        *bit_f = b;
        return OK;
ERROR:
        tld_bitfield_free(b);
        return FAIL;
}

void tld_bitfield_free(tld_bitfield *b)
{
        if(b){
                if(b->m){
                        gfree(b->m);
                }
                free(b);
        }
}

int tld_bitfield_reset(tld_bitfield *b)
{
        ASSERT(b != NULL, "No bitfield");
        memset(b->m, 0, b->alloc_len * sizeof(uint64_t));
        return OK;
ERROR:
        return FAIL;
}

int tld_bitfield_set(tld_bitfield *b, int32_t index)
{
        ASSERT(b != NULL, "No bitfield");
        if(index < 0 || index >= b->len){
                return FAIL;
        }
        b->m[index >> BIT_SHIFT] |= (1ULL << (index & BIT_MASK));
        return OK;
ERROR:
        return FAIL;
}

int tld_bitfield_get(tld_bitfield *b, int32_t index, uint8_t* bit)
{
        ASSERT(b != NULL, "No bitfield");
        ASSERT(bit != NULL, "No output pointer");
        if(index < 0 || index >= b->len){
                return FAIL;
        }
        *bit = (b->m[index >> BIT_SHIFT] & (1ULL << (index & BIT_MASK))) != 0;
        return OK;
ERROR:
        return FAIL;
}

int tld_bitfield_clear(tld_bitfield *b, int32_t index)
{
        ASSERT(b != NULL, "No bitfield");
        if(index < 0 || index >= b->len){
                return FAIL;
        }
        b->m[index >> BIT_SHIFT] &= ~(1ULL << (index & BIT_MASK));
        return OK;
ERROR:
        return FAIL;
}

int tld_bitfield_copy(tld_bitfield *dst, tld_bitfield *src)
{
        ASSERT(dst != NULL, "No bitfield");
        ASSERT(src != NULL, "No bitfield");
        if(dst->len != src->len){
                ERROR_MSG("bitfields have different lengths");
        }
        memcpy(dst->m, src->m, src->alloc_len * sizeof(uint64_t));
        dst->len = src->len;
        dst->alloc_len = src->alloc_len;
        return OK;
ERROR:
        return FAIL;
}

int tld_bitfield_or(tld_bitfield *b1, tld_bitfield *b2,tld_bitfield* ret)
{
        ASSERT(b1 != NULL, "No bitfield");
        ASSERT(b2 != NULL, "No bitfield");
        ASSERT(ret != NULL, "No bitfield");
        if(b1->len != b2->len){
                ERROR_MSG("bitfields have different lengths");
        }
        if(ret->len != b1->len){
                ERROR_MSG("bitfields have different lengths");
        }

        int32_t len = b1->alloc_len;

        for(int i = 0; i <  len; i++){
                ret->m[i] = b1->m[i] | b2->m[i];
        }
        return OK;
ERROR:
        return FAIL;
}

/* here is an alternative implementation of popcountll using branchless code*/
int tld__bitfield_popcount(uint64_t x)
{
        x = x - ((x >> 1) & 0x5555555555555555ULL);
        x = (x & 0x3333333333333333ULL) + ((x >> 2) & 0x3333333333333333ULL);
        x = (x + (x >> 4)) & 0x0F0F0F0F0F0F0F0FULL;
        x = x + (x >> 8);
        x = x + (x >> 16);
        x = x + (x >> 32);
        return x & 0x7F;
}

int tld_bitfield_hamming(tld_bitfield *b1, tld_bitfield *b2,tld_bitfield* mask, int32_t* dist)
{
        /* making sure the bitfields have the same length */
        ASSERT(b1 != NULL, "No bitfield");
        ASSERT(b2 != NULL, "No bitfield");
        ASSERT(dist != NULL, "No output pointer");
        if(b1->len != b2->len || b2->alloc_len < b1->alloc_len){
                ERROR_MSG("bitfields have different lengths");
        }
        int32_t len = b1->alloc_len;
        int32_t count = 0;
        if(mask == NULL){
                for(int i = 0; i <  len; i++){
                        count += tld__bitfield_popcount(b1->m[i] ^ b2->m[i]);
                }
        }else{
                if(mask->len != b1->len || mask->alloc_len < len){
                        ERROR_MSG("mask and bitfields have different lengths");
                }
                for(int i = 0; i <  len; i++){
                        count += tld__bitfield_popcount((b1->m[i] ^ b2->m[i]) & mask->m[i]);
                }
        }
        *dist = count;
        return OK;
ERROR:
        return FAIL;
}

#undef BIT_MASK
#undef BIT_SHIFT
#undef BITS_W
/* ---- src/hash/tld-hash.c ---- */
#include <limits.h>

#include <stdio.h>

#define LOAD_FACTOR_THRESHOLD 0.75

/* ---- src/hash/tld-hash_struct.h ---- */
#ifndef TLD_HASH_STRUCT_H
#define TLD_HASH_STRUCT_H

typedef struct tld_hash_entry {
        tld_strbuf* key;
        tld_strbuf* value;
        struct tld_hash_entry* next; /* For handling collisions using chaining */
} tld_hash_entry;

typedef struct tld_hash {
        tld_hash_entry** table; /* Array of pointers to entries */
        tld_hash_entry* cur_entry;
        int cur_index;
        int table_size; /* Size of the hash table */
        int n; /* Number of entries */
        int n_rep;
        int status;
} tld_hash;

#endif

static  int tld__hash_entry_alloc(tld_hash_entry **entry);
static void tld__hash_entry_free(tld_hash_entry *n);

static unsigned int tld__hash_fnv1a(const char *str, int table_size);
static int tld__hash_resize(tld_hash *h);

/* The smallest table size in the prime list that is larger than size; 0 if none is. */
static int tld__hash_next_size(int size)
{
        static const int prime_sizes[] = {
                53, 97, 193, 389, 769, 1543, 3079, 6151,
                12289, 24593, 49157, 98317, 196613, 393241,
                786433, 1572869, 3145739, 6291469, 12582917,
                25165843, 50331653, 100663319, 201326611,
                402653189, 805306457, 1610612741
        };
        for (size_t i = 0; i < sizeof(prime_sizes) / sizeof(prime_sizes[0]); i++) {
                if (prime_sizes[i] > size) {
                        return prime_sizes[i];
                }
        }
        return 0;
}

int tld_hash_alloc(tld_hash **hash, int size)
{
        tld_hash* h = NULL;
        int new_size = 0;
        ASSERT(hash != NULL, "No output pointer");
        MMALLOC(h, sizeof(tld_hash));

        new_size = tld__hash_next_size(size);
        ASSERT(new_size > 0, "Requested hash size %d is too large", size);

        /* table_size stays 0 until the table exists, so tld_hash_free on the
           error path never walks a missing table */
        h->table_size = 0;
        h->table = NULL;

        h->n = 0;

        h->cur_index = 0;
        h->cur_entry = NULL;

        MMALLOC(h->table, sizeof(tld_hash_entry*) * new_size);
        h->table_size = new_size;
        for (int i = 0; i < h->table_size; i++) {
                h->table[i] = NULL;
        }
        *hash = h;
        return OK;
ERROR:
        if(h){
                tld_hash_free(h);
        }
        return FAIL;
}

void tld__hash_entry_free(tld_hash_entry *n)
{
        if(n){
                tld_strbuf_free(n->key);
                tld_strbuf_free(n->value);
                MFREE(n);
        }
}

void tld_hash_free(tld_hash *h)
{
        if(h){
                for(int i = 0; i < h->table_size; i++){
                        tld_hash_entry* entry = h->table[i];
                        while(entry){
                                tld_hash_entry* next = entry->next;
                                tld__hash_entry_free(entry);
                                entry = next;
                        }
                }

                MFREE(h->table);
                MFREE(h);
        }
}

static unsigned int tld__hash_fnv1a(const char *str, int table_size)
{
        unsigned int hash = 2166136261u;
        int c;
        while ((c = *str++)) {
                hash ^= c;
                hash *= 16777619;
        }
        return hash % table_size;
}

int tld__hash_entry_alloc(tld_hash_entry **entry)
{
        tld_hash_entry* e = NULL;
        MMALLOC(e, sizeof(tld_hash_entry));
        e->key = NULL;
        e->value = NULL;
        RUN(tld_strbuf_alloc(&e->key, 64));
        RUN(tld_strbuf_alloc(&e->value, 64));
        e->next = NULL;
        *entry = e;
        return OK;
ERROR:
        tld__hash_entry_free(e);
        return FAIL;
}

int tld__hash_resize(tld_hash *h)
{
        tld_hash_entry **new_table = NULL;

        int new_size = tld__hash_next_size(h->table_size);
        if (new_size == 0) {
                /* past the prime list: double the size, if that still fits in an int */
                ASSERT(h->table_size <= (INT_MAX - 1) / 2, "Hash table is too large to grow");
                new_size = h->table_size * 2 + 1;
        }

        MMALLOC(new_table, sizeof(tld_hash_entry*) * new_size);
        if (!new_table) return FAIL;

        /* Initialize new table */
        for (int i = 0; i < new_size; i++) {
                new_table[i] = NULL;
        }

        /* Rehash all existing entries */
        for (int i = 0; i < h->table_size; i++) {
                tld_hash_entry *entry = h->table[i];
                while (entry) {
                        tld_hash_entry *next = entry->next;
                        unsigned int new_index = tld__hash_fnv1a(TLD_STR(entry->key), new_size);
                        entry->next = new_table[new_index];
                        new_table[new_index] = entry;
                        entry = next;
                }
        }

        /* Replace old table with new table */
        MFREE(h->table);
        h->table = new_table;
        h->table_size = new_size;
        h->n_rep++;
        return OK;
ERROR:
        return FAIL;

}

/* Replace the stored value v with val. val may point into v itself (a value from
   tld_hash_get passed back in): then it is moved to the front instead of being cleared
   away before it is copied. */
static int tld__hash_set_value(tld_strbuf *v, const char *val)
{
        uintptr_t start = (uintptr_t) v->str;
        uintptr_t p = (uintptr_t) val;
        if(p >= start && p <= start + (uintptr_t) v->len){
                size_t n = strlen(val);
                memmove(v->str, val, n + 1);
                v->len = (int32_t) n;
                return OK;
        }
        RUN(tld_strbuf_clear(v));
        RUN(tld_strbuf_append(v, val));
        return OK;
ERROR:
        return FAIL;
}

int tld_hash_add(tld_hash **hash, const char *key, const char *val)
{
        tld_hash* h = NULL;
        tld_hash_entry* new_entry = NULL;
        int allocated = 0;
        ASSERT(hash != NULL, "No Map pointer");
        ASSERT(key != NULL, "No key");
        ASSERT(val != NULL, "No value");
        if(*hash){
                h = *hash;
        }else{
                RUN(tld_hash_alloc(&h, 1024));
                allocated = 1;
        }

        ASSERT(h != NULL, "No Map");

        double load_factor = (double)h->n / (double)h->table_size;

        if (load_factor > LOAD_FACTOR_THRESHOLD) {
                RUN(tld__hash_resize(h));
        }

        unsigned int index = tld__hash_fnv1a(key, h->table_size);

        /* Check if key already exists */
        tld_hash_entry* current = h->table[index];
        while (current) {
                if (strcmp(TLD_STR(current->key), key) == 0) {
                        RUN(tld__hash_set_value(current->value, val));
                        return OK;
                }
                current = current->next;
        }

        /* Key does not exist, create a new entry */
        RUN(tld__hash_entry_alloc(&new_entry));

        RUN(tld_strbuf_append(new_entry->key, key));
        RUN(tld_strbuf_append(new_entry->value, val));
        new_entry->next = h->table[index];
        h->table[index] = new_entry;
        h->n++;

        *hash = h;
        return OK;
ERROR:
        tld__hash_entry_free(new_entry);
        /* a table allocated by this call is not handed back on failure */
        if(allocated){
                tld_hash_free(h);
        }
        return FAIL;
}

int tld_hash_get(tld_hash *h, const char *key, const char **val)
{
        ASSERT(h != NULL, "No hash");
        ASSERT(key != NULL, "No key");
        ASSERT(val != NULL, "No output pointer");

        unsigned int index = tld__hash_fnv1a(key, h->table_size);
        tld_hash_entry* entry = h->table[index];

        while (entry) {
                if (strcmp(TLD_STR(entry->key), key) == 0) {
                        *val = TLD_STR(entry->value);
                        return OK;
                }
                entry = entry->next;
        }

        *val = NULL;
        return FAIL;
ERROR:
        return FAIL;
}

int tld_hash_del(tld_hash *h, const char *key)
{
        ASSERT(h != NULL, "No hash");
        ASSERT(key != NULL, "No key");

        unsigned int index = tld__hash_fnv1a(key, h->table_size);
        tld_hash_entry* entry = h->table[index];
        tld_hash_entry* prev = NULL;

        while(entry){
                if(strcmp(TLD_STR(entry->key), key) == 0){
                        if(prev){
                                prev->next = entry->next;
                        }else{
                                h->table[index] = entry->next;
                        }
                        tld__hash_entry_free(entry);
                        h->n--;
                        return OK;
                }
                prev = entry;
                entry = entry->next;
        }

        return FAIL;
ERROR:
        return FAIL;
}

int tld_hash_rename(tld_hash *h, const char *key, const char *new_key) {
        tld_strbuf* tmp = NULL;
        ASSERT(h != NULL, "No hash");
        ASSERT(key != NULL, "No key");
        ASSERT(new_key != NULL, "No new key");

        unsigned int index = tld__hash_fnv1a(key, h->table_size);
        tld_hash_entry* entry = h->table[index];

        while (entry) {
                if (strcmp(TLD_STR(entry->key), key) == 0) {
                        if(strcmp(key, new_key) == 0){
                                return OK;
                        }
                        RUN(tld_strbuf_alloc(&tmp, 64));
                        RUN(tld_strbuf_copy(tmp, entry->value));
                        /* Add the new key first so a failure leaves the old
                           entry in place, then remove the old key. */
                        RUN(tld_hash_add(&h, new_key, TLD_STR(tmp)));
                        RUN(tld_hash_del(h, key));
                        tld_strbuf_free(tmp);
                        return OK;
                }
                entry = entry->next;
        }

        return FAIL;
ERROR:
        tld_strbuf_free(tmp);
        return FAIL;
}

int tld_hash_iter_init(tld_hash *h)
{
        ASSERT(h != NULL, "No Map");
        h->cur_index = 0;
        h->cur_entry = NULL;
        while(h->cur_index < h->table_size && h->table[h->cur_index] == NULL){
                h->cur_index++;
        }

        /* Set current_entry to the first non-null entry if found. */
        if(h->cur_index < h->table_size){
                h->cur_entry = h->table[h->cur_index];
        }
        return OK;
ERROR:
        return FAIL;
}

int tld_hash_iter_next(tld_hash* h, const char **key, const char **value)
{
        ASSERT(h != NULL, "Iterator is NULL");
        ASSERT(key != NULL, "Key pointer is NULL");
        ASSERT(value != NULL, "Value pointer is NULL");

        /* If there is no current entry, return 0 (no more entries). */
        if (h->cur_entry == NULL) {
                return FAIL;
        }

        *key = TLD_STR(h->cur_entry->key);
        *value = TLD_STR(h->cur_entry->value);

        /* Move to the next entry in the current linked list. */
        h->cur_entry = h->cur_entry->next;

        /* If the current entry is NULL, move to the next index in the table. */
        while(h->cur_entry == NULL && h->cur_index + 1 < h->table_size){
                h->cur_index++;
                h->cur_entry = h->table[h->cur_index];
        }

        return OK;
ERROR:
        return FAIL;
}

#undef LOAD_FACTOR_THRESHOLD
/* ---- src/json/tld-json_mem.c ---- */



int tld_json_obj_alloc(tld_json_obj **node)
{
        tld_json_obj *n = NULL;
        const int want = 4;
        ASSERT(node != NULL, "No output pointer");
        MMALLOC(n, sizeof(tld_json_obj));
        n->key = NULL;
        n->v = NULL;
        n->n_alloc = 0;         /* counts slots that really exist, so n can always be freed */
        n->n = 0;
        n->top_level_arr = 0;

        MMALLOC(n->key, sizeof(tld_strbuf*) * want);
        MMALLOC(n->v, sizeof(tld_json_val*) * want);

        while(n->n_alloc < want){
                int i = n->n_alloc;
                n->key[i] = NULL;
                n->v[i] = NULL;
                RUN(tld_strbuf_alloc(&n->key[i], 16));
                if(tld_json_val_alloc(&n->v[i]) != OK){
                        tld_strbuf_free(n->key[i]);
                        ERROR_MSG("Could not allocate a JSON object");
                }
                n->n_alloc++;
        }
        *node = n;
        return OK;
ERROR:
        if(n){
                tld_json_obj_free(n);
        }
        return FAIL;
}

void tld_json_obj_free(tld_json_obj *n)
{
        if(n){
                for(int i = 0 ;i < n->n_alloc;i++){
                        tld_json_val_free(n->v[i]);
                        tld_strbuf_free(n->key[i]);
                }

                MFREE(n->key);
                MFREE(n->v);
                MFREE(n);
        }
}

int tld_json_obj_copy(tld_json_obj **target, tld_json_obj *s)
{
        tld_json_obj* t = NULL;
        ASSERT(s != NULL, "No source object");
        ASSERT(target != NULL, "No output pointer");
        RUN(tld_json_obj_alloc(&t));
        for(int i = 0; i < s->n;i++){
                RUN(tld_strbuf_append(t->key[i], TLD_STR(s->key[i])));
                RUN(tld_json_val_copy(t->v[i], s->v[i]));
                t->n++;
                RUN(tld__json_obj_chk_space(t));
        }
        t->top_level_arr = s->top_level_arr;

        *target = t;
        return OK;
ERROR:
        if(t){
                tld_json_obj_free(t);
        }
        return FAIL;
}

int tld__json_obj_chk_space(tld_json_obj *n)
{
        if(n->n == n->n_alloc){
                RUN(tld__json_obj_realloc(n));
        }
        return OK;
ERROR:
        return FAIL;
}

int tld__json_obj_realloc(tld_json_obj *n)
{
        /* Grow the arrays first; n_alloc only counts slots that really exist, so a
         * failure part-way leaves the object consistent (and freeable). */
        int target = n->n_alloc + n->n_alloc / 2 + 1;

        MREALLOC(n->key, sizeof(tld_strbuf*) * target);
        MREALLOC(n->v, sizeof(tld_json_val*) * target);

        while(n->n_alloc < target){
                int i = n->n_alloc;
                n->key[i] = NULL;
                n->v[i] = NULL;
                if(tld_strbuf_alloc(&n->key[i], 16) != OK){
                        ERROR_MSG("Could not grow JSON object");
                }
                if(tld_json_val_alloc(&n->v[i]) != OK){
                        tld_strbuf_free(n->key[i]);
                        n->key[i] = NULL;
                        ERROR_MSG("Could not grow JSON object");
                }
                n->v[i]->type = TLD_JSON_NULL;
                n->n_alloc++;
        }
        return OK;
ERROR:
        return FAIL;
}

int tld_json_arr_alloc(tld_json_arr **arr)
{
        tld_json_arr* n = NULL;
        const int want = 16;
        ASSERT(arr != NULL, "No output pointer");
        MMALLOC(n, sizeof(tld_json_arr));
        n->n_alloc = 0;         /* counts slots that really exist, so n can always be freed */
        n->n = 0;
        n->read_head = 0;
        n->v = NULL;
        MMALLOC(n->v,sizeof(tld_json_val*) * want);
        while(n->n_alloc < want){
                n->v[n->n_alloc] = NULL;
                RUN(tld_json_val_alloc(&n->v[n->n_alloc]));
                n->n_alloc++;
        }
        *arr = n;
        return OK;
ERROR:
        if(n){
                tld_json_arr_free(n);
        }
        return FAIL;
}

void tld_json_arr_free(tld_json_arr *n)
{
        if(n){
                if(n->v){
                        for(int i = 0; i < n->n_alloc;i++){
                                tld_json_val_free(n->v[i]);
                        }
                        MFREE(n->v);
                }
                MFREE(n);
        }
}

/* <> arr copy must be implemented here  */
int tld_json_arr_copy(tld_json_arr **t, tld_json_arr *s)
{
        tld_json_arr* n = NULL;
        ASSERT(s != NULL, "No source array");
        ASSERT(t != NULL, "No output pointer");
        RUN(tld_json_arr_alloc(&n));
        for(int i = 0; i < s->n;i++){
                RUN(tld_json_val_copy(n->v[n->n] , s->v[i]));
                n->n++;
                RUN(tld__json_arr_chk_space(n));
        }
        *t = n;
        return OK;
ERROR:
        tld_json_arr_free(n);
        return FAIL;
}

int tld__json_arr_chk_space(tld_json_arr *n)
{
        if(n->n == n->n_alloc){
                RUN(tld__json_arr_realloc(n));
        }
        return OK;
ERROR:
        return FAIL;
}

int tld__json_arr_realloc(tld_json_arr *n)
{
        /* As for objects: n_alloc only counts slots that exist. */
        int target = n->n_alloc + n->n_alloc / 2 + 1;

        MREALLOC(n->v, sizeof(tld_json_val*) * target);
        while(n->n_alloc < target){
                int i = n->n_alloc;
                n->v[i] = NULL;
                RUN(tld_json_val_alloc(&n->v[i]));
                n->n_alloc++;
        }
        return OK;
ERROR:
        return FAIL;
}

int tld_json_val_alloc(tld_json_val **node)
{
        tld_json_val* n = NULL;
        ASSERT(node != NULL, "No output pointer");
        MMALLOC(n, sizeof(tld_json_val));
        n->type = TLD_JSON_NULL;
        *node = n;
        return OK;
ERROR:
        return FAIL;
}

/* Release whatever v owns and mark it empty. */
static void tld__json_val_clear(tld_json_val *v)
{
        switch (v->type) {
        case TLD_JSON_STR:
                tld_strbuf_free(v->value.str);
                break;
        case TLD_JSON_ARR:
                tld_json_arr_free(v->value.arr);
                break;
        case TLD_JSON_OBJ:
                tld_json_obj_free(v->value.obj);
                break;
        default:
                break;
        }
        v->type = TLD_JSON_NULL;
}

void tld_json_val_free(tld_json_val* n)
{
        if(n){
                tld__json_val_clear(n);
                MFREE(n);
        }
}

/* Deep copy s into t. Whatever t held before is released, so t may hold a
   value of another type. The copy is built first, so s may live inside t. */
int tld_json_val_copy(tld_json_val *t, tld_json_val *s)
{
        tld_json_val tmp;
        ASSERT(t != NULL,"No target");
        ASSERT(s != NULL,"No source");

        if(t == s){
                return OK;
        }
        tmp.type = s->type;
        switch(s->type){
        case TLD_JSON_OBJ:
                tmp.value.obj = NULL;
                if(s->value.obj){
                        RUN(tld_json_obj_copy(&tmp.value.obj, s->value.obj));
                }
                break;
        case TLD_JSON_ARR:
                tmp.value.arr = NULL;
                if(s->value.arr){
                        RUN(tld_json_arr_copy(&tmp.value.arr, s->value.arr));
                }
                break;
        case TLD_JSON_STR:
                tmp.value.str = NULL;
                if(s->value.str){
                        RUN(tld_strbuf_alloc(&tmp.value.str, s->value.str->len + 1));
                        RUN(tld_strbuf_copy(tmp.value.str, s->value.str));
                }
                break;
        case TLD_JSON_DBL:
                tmp.value.d_num = s->value.d_num;
                break;
        case TLD_JSON_INT:
                tmp.value.i_num = s->value.i_num;
                break;
        case TLD_JSON_BOOL_TRUE:
        case TLD_JSON_BOOL_FALSE:
                tmp.value.b_num = s->value.b_num;
                break;
        case TLD_JSON_NULL:
                break;
        }
        tld__json_val_clear(t);
        *t = tmp;
        return OK;
ERROR:
        return FAIL;
}
