#include <math.h>

int tld_shannon(double *vec, int n, double *entropy)
{
        double t = 0.0;
        double s = 0.0;
        ASSERT(vec != NULL, "No vector");
        ASSERT(entropy != NULL, "No output pointer");
        ASSERT(n > 0, "Need at least one value");
        for(int i = 0; i < n;i++){
                ASSERT(vec[i] >= 0.0, "Value %d is negative or NaN", i);
                t += vec[i];
        }
        if(t == 0.0){
                *entropy = 0.0;
                return OK;
        }
        for(int i = 0; i < n;i++){
                if(vec[i]){
                        double p = vec[i] / t;
                        s += p * log2(p);
                }
        }

        s = s * -1.0;
        *entropy = s;
        return OK;
ERROR:
        return FAIL;
}

int tld_mean(double *vec, int n, double *mean)
{
        ASSERT(vec != NULL, "No vector");
        ASSERT(mean != NULL, "No output pointer");
        ASSERT(n > 0, "Need at least one value");
        double m = 0.0;
        for(int i = 0; i < n;i++){
                m += vec[i];
        }
        m /= (double) n;
        *mean = m;
        return OK;
ERROR:
        return FAIL;
}

/* sum of (a[i] - mean(a)) * (b[i] - mean(b)): n times the population covariance, and
   with a == b n times the population variance. */
static int tld__stats_codev(const double *a, const double *b, int n, double *sum)
{
        double mean_a = 0.0;
        double mean_b = 0.0;
        double c = 0.0;
        RUN(tld_mean((double *) a, n, &mean_a));
        RUN(tld_mean((double *) b, n, &mean_b));
        for(int i = 0; i < n; i++){
                c += (a[i] - mean_a) * (b[i] - mean_b);
        }
        *sum = c;
        return OK;
ERROR:
        return FAIL;
}

int tld_pop_variance(double *vec, int n, double *variance)
{
        double v = 0.0;
        ASSERT(variance != NULL, "No output pointer");
        RUN(tld__stats_codev(vec, vec, n, &v));
        *variance = v / (double) n;
        return OK;
ERROR:
        return FAIL;
}

int tld_sample_variance(double *vec, int n, double *variance)
{
        double v = 0.0;
        ASSERT(variance != NULL, "No output pointer");
        ASSERT(n > 1, "Sample variance needs at least two values");
        RUN(tld__stats_codev(vec, vec, n, &v));
        *variance = v / (double) (n - 1);
        return OK;
ERROR:
        return FAIL;
}

int tld_standardise(double *vec, int n, double *mean, double *stdev)
{
        double m;
        double variance;
        double s;
        ASSERT(mean != NULL, "No output pointer");
        ASSERT(stdev != NULL, "No output pointer");

        RUN(tld_mean(vec, n, &m));
        RUN(tld_sample_variance(vec, n, &variance));

        s = sqrt(variance);
        if(s == 0.0){
                ERROR_MSG("Standard deviation is zero");
        }
        for(int i = 0; i < n;i++){
                vec[i] = (vec[i] -m) / s;
        }

        *mean = m;
        *stdev = s;
        return OK;
ERROR:
        return FAIL;
}

int tld_sample_covariance(double *vec_a, double *vec_b, int n, double *cov)
{
        double c = 0.0;
        ASSERT(cov != NULL, "No output pointer");
        ASSERT(n > 1, "Sample covariance needs at least two values");
        RUN(tld__stats_codev(vec_a, vec_b, n, &c));
        *cov = c / (double) (n - 1);
        return OK;
ERROR:
        return FAIL;
}

int tld_pop_covariance(double *vec_a, double *vec_b, int n, double *cov)
{
        double c = 0.0;
        ASSERT(cov != NULL, "No output pointer");
        RUN(tld__stats_codev(vec_a, vec_b, n, &c));
        *cov = c / (double) n;
        return OK;
ERROR:
        return FAIL;
}

int tld_pearson_corr(double *vec_a, double *vec_b, int n, double *corr)
{
        double var_a;
        double var_b;

        double cov;
        double c;
        ASSERT(corr != NULL, "No output pointer");
        RUN(tld_pop_variance(vec_a, n, &var_a));
        RUN(tld_pop_variance(vec_b, n, &var_b));

        RUN(tld_pop_covariance(vec_a, vec_b, n, &cov));

        c = sqrt(var_a * var_b);
        if(c == 0){
                c = 0;
        }else{
                c = cov / c;
        }

        *corr = c;
        return OK;
ERROR:
        return FAIL;
}

int tld_sigmoid(double x, double *out)
{
        /* Define truncation limits based on double-precision floating point */
        const double MAX_X = 709.782712893384; /* Approximately log(DBL_MAX) */
        const double MIN_X = -709.782712893384; /* Approximately log(DBL_MIN) */
        double y;
        ASSERT(out != NULL, "No output pointer");
        if(isnan(x)){
                y = NAN;
                *out = y;
                return OK;
        }

        /* Handle positive and negative infinity */
        if(isinf(x)){
                if (x > 0){
                        y = 1.0;
                        *out = y;
                        return OK;

                }else{
                        y = 0.0;
                        *out = y;
                        return OK;
                }
        }

        /* Truncate x to prevent overflow */
        if(x > MAX_X){
                y = 1.0;
                *out = y;
                return OK;
        }else if(x < MIN_X){
                y = 0.0;
                *out = y;
                return OK;
        }

        /* Compute sigmoid in a numerically stable way */

        if(x < 0.0){
                y = exp(x);
                y = y / (1.0 + y);
        }else{
                y = 1.0 / (1.0 + exp(-x));
        }
        *out = y;
        return OK;
ERROR:
        return FAIL;
}

int tld_normal_pdf(double x, double mu, double sigma, double* p)
{
        double z;
        ASSERT(p != NULL, "No output pointer");
        ASSERT(sigma > 0.0, "stdev must be positive.");
        z = (x - mu) / sigma;

        *p = exp(-z*z*0.5) / (sigma * sqrt(2. * 3.14159265358979323846264338328));

        return OK;
ERROR:
        return FAIL;
}
/* ---- src/stats/tld-kde.c ---- */
#include <math.h>
#include <float.h>
#include <stdint.h>
/*
  adopted from:

  https://metacpan.org/release/JANERT/Statistics-KernelEstimation-0.05/source/lib/Statistics/KernelEstimation.pm
*/
static int tld__kde_copy_steps(double *data, int data_len, double ***ret);
static int tld__kde_create_steps(double *data, int data_len, int n_steps, double band, double*** ret);
static int tld__kde_default_bandwidth(double *x,double* cnt, int len, double* band);
static int tld__kde_eval(double **ladder, int n_pts, const double *data, const double *cnt, int data_len, double band, double total);

int tld_kde_pdf(double *data, int data_len, int n_steps, double ***out)
{
        double total_cnt = 0.0;
        double band = 0.1;

        double** ladder = NULL;

        ASSERT(data != NULL, "No data");
        ASSERT(out != NULL, "No output pointer");
        ASSERT(data_len > 0,"No data len?");
        ASSERT(n_steps > 0,"Number of steps must be positive");

        RUN(tld__kde_default_bandwidth(data,NULL,data_len,&band));

        RUN(tld__kde_create_steps(data,data_len, n_steps, band, &ladder));

        total_cnt = data_len;
        RUN(tld__kde_eval(ladder, n_steps, data, NULL, data_len, band, total_cnt));

        *out = ladder;

        return OK;
ERROR:
        if(ladder){
                gfree(ladder);
        }
        return FAIL;
}

int tld_kde_count_pdf(double *data,double* cnt, int data_len, double*** out)
{
        double total_cnt = 0.0;
        double band = 0.1;

        double** ladder = NULL;

        ASSERT(data != NULL, "No data");
        ASSERT(cnt != NULL, "No counts");
        ASSERT(out != NULL, "No output pointer");
        ASSERT(data_len > 0,"No data len?");

        total_cnt = 0.0;
        for(int i = 0; i < data_len; i++){
                ASSERT(cnt[i] >= 0.0, "Count %d is negative or NaN", i);
                total_cnt += cnt[i];
        }
        ASSERT(total_cnt > 0.0, "Total count is zero");

        RUN(tld__kde_copy_steps(data,data_len, &ladder ));

        RUN(tld__kde_default_bandwidth(data,cnt,data_len,&band));

        RUN(tld__kde_eval(ladder, data_len, data, cnt, data_len, band, total_cnt));

        *out = ladder;

        return OK;
ERROR:
        if(ladder){
                gfree(ladder);
        }
        return FAIL;
}

/* ladder[i][1] = sum over j of w[j] * N(ladder[i][0]; data[j], band) / total, for
   i < n_pts, with w = cnt, or 1 when cnt is NULL. */
int tld__kde_eval(double **ladder, int n_pts, const double *data, const double *cnt, int data_len, double band, double total)
{
        for(int i = 0; i < n_pts; i++){
                double d = 0.0;
                for(int j = 0; j < data_len; j++){
                        double add_d = 0.0;
                        RUN(tld_normal_pdf(ladder[i][0], data[j], band, &add_d));
                        /* two statements: one expression may be fused into an fma */
                        add_d = add_d * (cnt ? cnt[j] : 1.0);
                        d += add_d;
                }
                ladder[i][1] = d / total;
        }
        return OK;
ERROR:
        return FAIL;
}

int tld__kde_copy_steps(double *data, int data_len, double ***ret)
{
        double** x = NULL;
        galloc(&x, data_len,2);

        for(int i = 0; i < data_len;i++){
                x[i][0] = data[i];
                x[i][1] = 0.0;
        }
        *ret = x;
        return OK;
ERROR:
        if(x){
                gfree(x);
        }
        return FAIL;
}

/* Evaluation points: n_steps bin centres spanning [min, max]. When all
   data are equal the range is empty, so span mean +/- 4 bandwidths. */
int tld__kde_create_steps(double *data, int data_len, int n_steps, double band, double*** ret)
{
        double** x = NULL;
        double min = DBL_MAX;
        double max = -DBL_MAX;
        double step = 0.0;
        for(int i = 0;i < data_len;i++){
                if(max < data[i]){
                        max = data[i];
                }
                if(min > data[i]){
                        min = data[i];
                }
        }
        if(!(max > min)){
                min = min - 4.0 * band;
                max = max + 4.0 * band;
        }
        step = (max- min)  / (double)(n_steps);
        galloc(&x, n_steps,2);

        for(int i = 0; i < n_steps;i++){
                x[i][0] = min + (double) i * step + step / 2.0;
                x[i][1] = 0.0;
        }
        *ret = x;
        return OK;
ERROR:
        if(x){
                gfree(x);
        }
        return FAIL;

}

/* Silverman-style bandwidth sigma * (3n/4)^(-1/5). The variance is
   computed in two passes (mean first, then squared deviations) to avoid
   the cancellation of E[x^2] - E[x]^2 for data with a large offset. For
   constant data the bandwidth falls back to 1e-3 * |mean|, or 1.0 when
   the mean is zero. */
int tld__kde_default_bandwidth(double *x,double* cnt, int len, double* band)
{
        double sum_x = 0.0;
        double sum_dd = 0.0;
        double mean;
        double var;
        double sigma;
        double sum = 0.0;
        double b;

        for(int i = 0; i < len; i++){
                double w = cnt ? cnt[i] : 1.0;
                sum_x += w * x[i];
                sum += w;
        }
        ASSERT(sum > 0.0, "Total weight is zero");
        mean = sum_x / sum;
        ASSERT(isfinite(mean), "Data contain NaN or infinite values");

        for(int i = 0; i < len; i++){
                double w = cnt ? cnt[i] : 1.0;
                double d = x[i] - mean;
                sum_dd += w * d * d;
        }
        var = sum_dd / sum;
        if(!(var > 0.0)){
                var = 0.0;
        }
        sigma = sqrt(var);

        b = sigma * pow(3.0 * sum / 4.0 , -1.0 / 5.0 );
        if(!(b > 0.0)){
                b = fabs(mean) * 1e-3;
                if(!(b > DBL_MIN)){
                        b = 1.0;
                }
        }
        ASSERT(isfinite(b), "Bandwidth is not finite");
        *band = b;
        return OK;
ERROR:
        return FAIL;
}
/* ---- src/stats/tld-quantile.c ---- */

#include <math.h>

typedef struct {
        double v;
        int idx;
} tld__qnorm_item;

static int tld__qnorm_item_cmp (const void *a, const void *b);

/* Quantile normalisation of the m columns of an n x m matrix (in place).
   The reference distribution is the mean over columns of the sorted
   values. Each group of tied values in a column covers a run of sorted
   positions and gets the mean of the reference values over that run. */
int tld_quantile_normalise(double **data, int n, int m)
{
        double** data_rank = NULL;
        tld__qnorm_item* l = NULL;

        double sum = 0.0;

        ASSERT(data != NULL, "No data");
        ASSERT(n > 0, "Need at least one row");
        ASSERT(m > 0, "Need at least one column");

        for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                        ASSERT(!isnan(data[i][j]), "NaN at row %d column %d", i, j);
                }
        }

        galloc(&data_rank,n,m);
        MMALLOC(l, sizeof(tld__qnorm_item) * (size_t) n);

        /* Sorted values of each column */
        for(int column = 0; column < m; column++){
                for(int i = 0; i < n; i++){
                        l[i].idx = i;
                        l[i].v = data[i][column];
                }
                qsort(l, (size_t) n, sizeof(tld__qnorm_item), tld__qnorm_item_cmp);

                for(int i = 0;i < n;i++){
                        data_rank[i][column] = l[i].v;
                }
        }

        /* Reference quantiles: mean across columns at each sorted position */
        for(int i = 0; i < n;i++){
                sum = 0.0;
                for(int j = 0; j < m;j++){
                        sum += data_rank[i][j];
                }
                sum /= (double) m;
                data_rank[i][0] = sum;
        }

        for(int column = 0; column < m; column++){
                for(int i = 0; i < n; i++){
                        l[i].idx = i;
                        l[i].v = data[i][column];
                }
                qsort(l, (size_t) n, sizeof(tld__qnorm_item), tld__qnorm_item_cmp);

                int start = 0;
                while(start < n){
                        int end = start + 1;
                        while(end < n && l[end].v == l[start].v){
                                end++;
                        }
                        sum = 0.0;
                        for(int k = start; k < end; k++){
                                sum += data_rank[k][0];
                        }
                        sum /= (double) (end - start);
                        for(int k = start; k < end; k++){
                                data[l[k].idx][column] = sum;
                        }
                        start = end;
                }
        }

        gfree(data_rank);
        MFREE(l);
        return OK;
ERROR:
        if(data_rank){
                gfree(data_rank);
        }
        if(l){
                MFREE(l);
        }
        return FAIL;
}

int tld__qnorm_item_cmp (const void *a, const void *b)
{
        const tld__qnorm_item *one = a;
        const tld__qnorm_item *two = b;
        if(one->v > two->v){
                return 1;
        }else if(one->v < two->v){
                return -1;
        }
        /* Equal values: order by original index so the sort is deterministic */
        if(one->idx > two->idx){
                return 1;
        }else if(one->idx < two->idx){
                return -1;
        }
        return 0;
}
/* ---- src/stats/tld-auc.c ---- */


#include <float.h>
#include <math.h>

struct tld__auc_pt {
        double Y;
        double Y_hat;
};

static int tld__auc_sweep(double *Y, double *Y_hat, int n, double *auc_out, double *thres_out);

/* qsort comparator: ascending Y_hat */
static int tld__auc_pt_sort(const void *a, const void *b) {
        const struct tld__auc_pt *one = a;
        const struct tld__auc_pt *two = b;

        if (one->Y_hat < two->Y_hat) {
                return -1;
        } else if (one->Y_hat > two->Y_hat) {
                return 1;
        } else {
                return 0;
        }
}

/* Sorts the scores, sweeps the ROC curve from the highest score down,
   accumulates the area with the trapezoidal rule (tied scores form one
   step) and records the score nearest to the (0,1) corner. */
int tld__auc_sweep(double *Y, double *Y_hat, int n, double *auc_out, double *thres_out)
{
        struct tld__auc_pt* l = NULL;
        double thres = 0.0;
        double auc = 0.0;
        double tpr = 0.0;
        double fpr = 0.0;
        double last_tpr = 0.0;
        double last_fpr = 0.0;
        double best_distance = INFINITY;
        int tp = 0;
        int fp = 0;
        int total_positive = 0;
        int total_negative = 0;

        ASSERT(n > 0, "TLD auc needs more than 0 datapoints");
        ASSERT(Y != NULL, "No labels");
        ASSERT(Y_hat != NULL, "No predictions");

        MMALLOC(l, sizeof(struct tld__auc_pt) * (size_t) n);

        for(int i = 0; i < n; i++) {
                if(!(Y[i] >= 0.0 && Y[i] <= 1.0)) {
                        ERROR_MSG("label %d out of range: %f", i, Y[i]);
                }
                if(isnan(Y_hat[i])) {
                        ERROR_MSG("prediction %d is NaN", i);
                }
                l[i].Y = Y[i];
                l[i].Y_hat = Y_hat[i];
                if (Y[i] == 1.0) {
                        total_positive++;
                } else {
                        total_negative++;
                }
        }

        if(total_positive == 0 || total_negative == 0) {
                ERROR_MSG("AUC needs both classes (%d positive, %d negative)", total_positive, total_negative);
        }

        qsort(l, (size_t) n, sizeof(struct tld__auc_pt), tld__auc_pt_sort);

        for (int i = n - 1; i >= 0; i--) {
                if(l[i].Y == 1.0){
                        tp++;
                } else {
                        fp++;
                }

                if(i == 0 || l[i].Y_hat != l[i-1].Y_hat){
                        tpr = (double)tp / (double)total_positive;
                        fpr = (double)fp / (double)total_negative;

                        auc += (fpr - last_fpr) * (tpr + last_tpr) / 2.0;

                        double distance = sqrt(fpr * fpr + (1.0 - tpr) * (1.0 - tpr));
                        if (distance < best_distance) {
                                best_distance = distance;
                                thres = l[i].Y_hat;
                        }

                        last_tpr = tpr;
                        last_fpr = fpr;
                }
        }

        *auc_out = auc;
        *thres_out = thres;

        MFREE(l);
        return OK;
ERROR:
        if(l){
                MFREE(l);
        }
        return FAIL;
}

/* The best threshold is the score closest to the (0,1) corner of the ROC curve;
   samples with Y_hat >= threshold are called positive. */
int tld_auc(double *Y, double *Y_hat, int n, double *t, double *auc)
{
        double thres = 0.0;
        double area = 0.0;
        RUN(tld__auc_sweep(Y, Y_hat, n, &area, &thres));
        if(t){
                *t = thres;
        }
        if(auc){
                *auc = area;
        }
        return OK;
ERROR:
        return FAIL;
}
/* ---- src/logsum/tld-logsum.c ---- */
#include <pthread.h>

#include <math.h>
#include <float.h>

#define TLD__LOGSUM_SCALE 1000.0F
#define TLD__LOGSUM_SIZE 16000

static float tld__logsum_lookup[TLD__LOGSUM_SIZE];
static pthread_once_t tld__logsum_once = PTHREAD_ONCE_INIT;

static void tld__logsum_fill_table(void)
{
        for(int i = 0; i < TLD__LOGSUM_SIZE;i++){
                tld__logsum_lookup[i] = logf(1.0F + expf((float) -i / TLD__LOGSUM_SCALE));
        }
}

/* Thread-safe; calling it is optional, tld_logsum() initialises the table on first use. */
void tld_logsum_init(void)
{
        pthread_once(&tld__logsum_once, tld__logsum_fill_table);
}

float tld_logsum(const float a,const float b)
{
        if(isnan(a) || isnan(b)){
                return NAN;
        }
        const float max = TLD_MAX(a, b);
        const float min = TLD_MIN(a, b);

        if(  TLD_NEARLY_EQUAL(min, -INFINITY)){
                return max;
        }
        /* !(d < 15.7) also catches +inf - +inf = NaN */
        if( !((max-min) < 15.7F)){
                return max;
        }
        tld_logsum_init();
        return  max+ tld__logsum_lookup[(int)((max-min)*TLD__LOGSUM_SCALE)];
}

int tld_nearly_equal_float(float a, float b)
{
        const float min = FLT_MIN;
        float absa = fabsf(a);
        float absb = fabsf(b);
        float d = fabsf(a-b);
        int ret = 0;
        if(a == b){
                ret = 1;
        }else if (a == 0.0F || b == 0 || (absa + absb < min)){
                ret =  d < (FLT_EPSILON * min);
        }else{
                ret =  d / TLD_MIN((absa+absb), FLT_MAX) < FLT_EPSILON;
        }
        return ret;
}

int tld_nearly_equal_double(double a, double b)
{
        const double min = DBL_MIN;
        double absa = fabs(a);
        double absb = fabs(b);
        double d = fabs(a-b);
        int ret = 0;
        if(a == b){
                ret = 1;
        }else if (a == 0.0 || b == 0 || (absa + absb < min)){
                ret = d < (DBL_EPSILON * min);
        }else{
                ret = d / TLD_MIN((absa+absb), DBL_MAX) < DBL_EPSILON;
        }
        return ret;
}

#undef TLD__LOGSUM_SCALE
#undef TLD__LOGSUM_SIZE
/* ---- src/kdtree/tld-kdtree.c ---- */

#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <float.h>

/* A tree node: p is the point (the tree's dim doubles, owned by the yard), id the
   caller's id. */
typedef struct tld__kdtree_node {
        double* p;
        struct tld__kdtree_node* left;
        struct tld__kdtree_node* right;
        uint32_t id;
} tld__kdtree_node;

/* The yard owns every node and its point. nodes[0 .. n_node) are in the tree; the
   slots up to n_alloc are allocated and free for later points. Building and
   rebalancing only re-link these nodes, so they never allocate and never move a
   point between nodes. */
struct tld__kdyard {
        tld__kdtree_node** nodes;
        int n_alloc;
        int n_node;
        int vec_len;
};

/* rebalance_at: insertions between balance checks (10000; the oom test lowers it). */
struct tld_kdtree {
        tld__kdtree_node* root;
        struct tld__kdyard* yard;
        int rebalance_at;
        int n_step;
        int depth;
        int max_depth;
        int min_depth;
        int vec_len;
};

static int tld__kdtree_nn(const tld_kdtree *t, const tld__kdtree_node* n, const double *x, int depth, double* min_d, uint32_t *id);

static int tld__kdyard_alloc(struct tld__kdyard ** yard, int size, int len);
static int tld__kdyard_reserve(struct tld__kdyard *y, int n);
static void tld__kdyard_free(struct tld__kdyard *n);

static void tld__kdtree_node_set(tld_kdtree *t, tld__kdtree_node *n, const double *x, uint32_t id);
static double tld__kdtree_dist(const double *a, const double *b, int vec_len);
static void tld__kdtree_relink(tld_kdtree *t);
static tld__kdtree_node* tld__kdtree_link_balanced(tld__kdtree_node **v, int n, int depth, int dim, int *max_depth);
static void tld__kdtree_select_nth(tld__kdtree_node **v, int n, int k, int cd);
static int tld__kdtree_node_alloc(tld__kdtree_node **node, int size);
static void tld__kdtree_node_free(tld__kdtree_node *n);

int tld__kdtree_node_alloc(tld__kdtree_node **node, int size)
{
        tld__kdtree_node* n = NULL;
        MMALLOC(n, sizeof(tld__kdtree_node));
        galloc(&n->p, size);
        *node = n;
        return OK;
ERROR:
        tld__kdtree_node_free(n);
        return FAIL;
}

void tld__kdtree_node_free(tld__kdtree_node *n)
{
        if(n){
                gfree(n->p);
                MFREE(n);
        }
}

int tld__kdyard_alloc(struct tld__kdyard ** yard, int size, int len)
{
        struct tld__kdyard* n = NULL;
        MMALLOC(n, sizeof(struct tld__kdyard));
        n->vec_len = len;
        RUN(tld__kdyard_reserve(n, size));
        *yard = n;
        return OK;
ERROR:
        tld__kdyard_free(n);
        return FAIL;
}

/* Room for n more nodes after the ones in the tree, growing by at least half. On
   failure the yard is unchanged apart from extra free slots, so the tree is intact. */
int tld__kdyard_reserve(struct tld__kdyard *y, int n)
{
        int need = 0;
        int new_size = 0;
        ASSERT(n >= 0 && y->n_node <= INT32_MAX - n, "Too many points (%d more after %d)", n, y->n_node);
        need = y->n_node + n;
        if(need <= y->n_alloc){
                return OK;
        }
        new_size = y->n_alloc + y->n_alloc / 2 + 1;
        if(new_size < need || new_size < y->n_alloc){
                new_size = need;
        }
        MREALLOC(y->nodes, sizeof(tld__kdtree_node*) * (size_t) new_size);
        while(y->n_alloc < new_size){
                y->nodes[y->n_alloc] = NULL;
                RUN(tld__kdtree_node_alloc(&y->nodes[y->n_alloc], y->vec_len));
                y->n_alloc++;
        }
        return OK;
ERROR:
        return FAIL;
}

void tld__kdyard_free(struct tld__kdyard *n)
{
        if(n){
                for(int i = 0; i < n->n_alloc; i++){
                        tld__kdtree_node_free(n->nodes[i]);
                }
                MFREE(n->nodes);
                MFREE(n);
        }
}

int tld_kdtree_alloc(tld_kdtree **tree, int dim)
{
        tld_kdtree* t = NULL;
        ASSERT(tree != NULL, "No output pointer");
        ASSERT(dim > 0, "Number of dimensions must be positive (got %d)", dim);
        MMALLOC(t, sizeof(tld_kdtree));
        t->rebalance_at = 10000;
        t->vec_len = dim;
        RUN(tld__kdyard_alloc(&t->yard, 1024, dim));
        *tree = t;
        return OK;
ERROR:
        tld_kdtree_free(t);
        return FAIL;
}

void tld_kdtree_free(tld_kdtree *t)
{
        if(t){
                tld__kdyard_free(t->yard);
                MFREE(t);
        }
}

int tld_kdtree_reset(tld_kdtree *t)
{
        ASSERT(t != NULL, "No tree");
        t->root = NULL;
        t->yard->n_node = 0;
        t->depth = 0;
        t->max_depth = 0;
        t->min_depth = 0;
        return OK;
ERROR:
        return FAIL;
}

/* Put point x (the tree's vec_len doubles) and id into the free node n. */
void tld__kdtree_node_set(tld_kdtree *t, tld__kdtree_node *n, const double *x, uint32_t id)
{
        n->left = NULL;
        n->right = NULL;
        n->id = id;
        for(int i = 0; i < t->vec_len; i++){
                n->p[i] = x[i];
        }
}

/* Reorder v[0..n) so that v[k] holds the node whose coordinate cd would be k-th in
   sorted order, with no larger value before it and no smaller one after it. */
void tld__kdtree_select_nth(tld__kdtree_node **v, int n, int k, int cd)
{
        int lo = 0;
        int hi = n - 1;
        while(lo < hi){
                const double pivot = v[lo + (hi - lo) / 2]->p[cd];
                int i = lo;
                int j = hi;
                while(i <= j){
                        while(v[i]->p[cd] < pivot){
                                i++;
                        }
                        while(v[j]->p[cd] > pivot){
                                j--;
                        }
                        if(i <= j){
                                tld__kdtree_node* tmp = v[i];
                                v[i] = v[j];
                                v[j] = tmp;
                                i++;
                                j--;
                        }
                }
                if(k <= j){
                        hi = j;
                }else if(k >= i){
                        lo = i;
                }else{
                        break;
                }
        }
}

/* Link v[0..n) into a balanced subtree splitting on coordinate depth % dim; returns
   its root. */
tld__kdtree_node* tld__kdtree_link_balanced(tld__kdtree_node **v, int n, int depth, int dim, int *max_depth)
{
        tld__kdtree_node* r = NULL;
        int mid = n / 2;
        if(n <= 0){
                return NULL;
        }
        tld__kdtree_select_nth(v, n, mid, depth % dim);
        r = v[mid];
        if(depth > *max_depth){
                *max_depth = depth;
        }
        r->left = tld__kdtree_link_balanced(v, mid, depth + 1, dim, max_depth);
        r->right = tld__kdtree_link_balanced(v + mid + 1, n - mid - 1, depth + 1, dim, max_depth);
        return r;
}

/* Rebuild the tree balanced from the nodes it holds. */
void tld__kdtree_relink(tld_kdtree *t)
{
        t->max_depth = 0;
        t->min_depth = 0;
        t->root = tld__kdtree_link_balanced(t->yard->nodes, t->yard->n_node, 0, t->vec_len, &t->max_depth);
}

int tld_kdtree_build(tld_kdtree *t, double **x, uint32_t *ids, int n)
{
        ASSERT(t != NULL, "No tree");
        ASSERT(n >= 0, "Negative number of points (%d)", n);
        ASSERT(n == 0 || (x != NULL && ids != NULL), "No points or ids");
        for(int i = 0; i < n; i++){
                ASSERT(x[i] != NULL, "Point %d is NULL", i);
        }
        RUN(tld__kdyard_reserve(t->yard, n));
        for(int i = 0; i < n; i++){
                tld__kdtree_node_set(t, t->yard->nodes[t->yard->n_node + i], x[i], ids[i]);
        }
        t->yard->n_node += n;
        tld__kdtree_relink(t);
        return OK;
ERROR:
        return FAIL;
}

int tld_kdtree_insert(tld_kdtree *t, double *x, uint32_t id)
{
        tld__kdtree_node* n = NULL;
        tld__kdtree_node** slot = NULL;
        int depth = 0;
        ASSERT(t != NULL, "No tree");
        ASSERT(x != NULL, "No point");

        RUN(tld__kdyard_reserve(t->yard, 1));
        n = t->yard->nodes[t->yard->n_node];
        tld__kdtree_node_set(t, n, x, id);
        t->yard->n_node++;

        slot = &t->root;
        while(*slot != NULL){
                const int cd = depth % t->vec_len;
                slot = n->p[cd] < (*slot)->p[cd] ? &(*slot)->left : &(*slot)->right;
                depth++;
        }
        *slot = n;
        if(depth > t->max_depth){
                t->max_depth = depth;
        }

        t->n_step = t->n_step + 1;
        if(t->n_step >= t->rebalance_at){
                int test = t->yard->n_node;
                int opt_d = 0;
                while(test){
                        test = test / 2;
                        opt_d++;
                }
                t->n_step = 0;
                if(abs(t->max_depth - opt_d) > 10){
                        tld__kdtree_relink(t);
                }
        }
        return OK;
ERROR:
        return FAIL;
}

int tld_kdtree_rebalance(tld_kdtree *t)
{
        ASSERT(t != NULL, "No tree");
        tld__kdtree_relink(t);
        return OK;
ERROR:
        return FAIL;
}

/* Depth-first nearest-neighbour search below n (at depth). The tree is only read, so
   searches of one tree may run at the same time. */
int tld__kdtree_nn(const tld_kdtree *t, const tld__kdtree_node* n, const double *x, int depth, double* min_d, uint32_t *id)
{
        double d = 0.0;
        int cd = 0;
        int near_left = 0;

        if(n == NULL){
                return OK;
        }
        d = tld__kdtree_dist(n->p, x, t->vec_len);
        if(d < *min_d){
                *min_d = d;
                *id = n->id;
        }
        cd = depth % t->vec_len;
        near_left = x[cd] < n->p[cd];
        tld__kdtree_nn(t, near_left ? n->left : n->right, x, depth + 1, min_d, id);
        /* the far side can hold a nearer point only if the splitting plane is closer
           than the best distance so far */
        if((n->p[cd] - x[cd]) * (n->p[cd] - x[cd]) < *min_d){
                tld__kdtree_nn(t, near_left ? n->right : n->left, x, depth + 1, min_d, id);
        }
        return OK;
}

int tld_kdtree_nn_search(tld_kdtree *t, double *x, uint32_t *id)
{
        double min_d = DBL_MAX;
        uint32_t best = 0;
        ASSERT(t != NULL, "No tree");
        ASSERT(x != NULL, "No point");
        ASSERT(id != NULL, "No id");
        ASSERT(t->root != NULL, "The tree is empty");
        RUN(tld__kdtree_nn(t, t->root, x, 0, &min_d, &best));
        *id = best;
        return OK;
ERROR:
        return FAIL;
}

int tld_kdtree_bf_search(tld_kdtree *t, double *x, uint32_t *id)
{
        double min_d = DBL_MAX;
        double d = 0.0;
        uint32_t best = 0;
        ASSERT(t != NULL, "No tree");
        ASSERT(x != NULL, "No point");
        ASSERT(id != NULL, "No id");
        ASSERT(t->yard->n_node > 0, "The tree is empty");
        for(int i = 0; i < t->yard->n_node; i++){
                d = tld__kdtree_dist(x, t->yard->nodes[i]->p, t->vec_len);
                if(d < min_d){
                        min_d = d;
                        best = t->yard->nodes[i]->id;
                }
        }
        *id = best;
        return OK;
ERROR:
        return FAIL;
}

/* Squared Euclidean distance between a and b (vec_len doubles). */
double tld__kdtree_dist(const double *a, const double *b, int vec_len)
{
        double d = 0.0;
        for(int i = 0; i < vec_len; i++){
                const double x = a[i] - b[i];
                d += x * x;
        }
        return d;
}
